package org.telegram.messenger.purple;public final class PurpleState {public static byte[] bytes;public static boolean fail;public static int writes;public static Runnable readHook;public static byte[] read(){if(readHook!=null)readHook.run();return bytes==null?null:bytes.clone();}public static boolean write(byte[] b){++writes;if(fail)return false;bytes=b.clone();return true;}}
